'use strict';

const mongoose = require('mongoose');

/** One text message between a ride's passenger and its assigned driver. */
const chatMessageSchema = new mongoose.Schema(
  {
    rideId: { type: mongoose.Schema.Types.ObjectId, ref: 'Ride', required: true },
    senderId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    senderRole: { type: String, enum: ['PASSENGER', 'DRIVER'], required: true },
    body: { type: String, required: true, trim: true, minlength: 1, maxlength: 500 },
    // Generated by the sending app; re-sending the same id (retry after a
    // dropped connection) returns the stored message instead of a duplicate.
    clientMessageId: { type: String, required: true, maxlength: 64 },
  },
  { timestamps: { createdAt: true, updatedAt: false } }
);

chatMessageSchema.index({ rideId: 1, senderId: 1, clientMessageId: 1 }, { unique: true });
chatMessageSchema.index({ rideId: 1, createdAt: 1, _id: 1 });

module.exports = mongoose.model('ChatMessage', chatMessageSchema);
